def replicate(grid,color,allow_self=True):
 R=len(grid); K=len(grid[0]); pts=[(r,c) for r in range(R) for c in range(K) if grid[r][c]==color]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts); shape=[(r-r0,c-c0) for r,c in pts]
 h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
 out=[row[:] for row in grid]
 anchors=[]
 for ar in range(R-h+1):
  for ac in range(K-w+1):
   if all(grid[ar+dr][ac+dc] in ((0,color) if allow_self else (0,)) for dr,dc in shape):
    anchors.append((ar,ac))
    for dr,dc in shape: out[ar+dr][ac+dc]=color
 return out,shape,anchors
